export const ComponentConfig = z.object({ "component_type": z.lazy(() => ComponentTypeEnum).describe("Component type:\n- bubble: Bubble chart (scatter plot with size dimension for 3-variable data)\n- categorical_bar: Bar chart with categorical x-axis (for example, regions or products)\n- choropleth: Choropleth map showing geographic data with color intensity by region (US states or world)\n- data_table_chart: Bar chart with auto-generated data table below showing values\n- financial_boxes: Financial metric boxes with values and growth indicators (for example, Revenue or EPS)\n- generic_timeseries: timeseries chart\n- header: Card header with title and description, automatically styled with theme\n- heatmap: 2D heatmap with color intensity representing values (for example, a correlation matrix)\n- histogram: Histogram chart showing frequency distribution of values\n- person_card: Person profile card with career, education, and about tabs\n- pie: Pie chart showing proportional data as slices of a circle\n- scatter: Scatter plot showing relationships between two continuous variables\n- table: Data table with configurable columns and rows\n- boxplot: Box plot showing statistical distributions (min, Q1, median, Q3, max)\n- treemap: Treemap chart showing hierarchical data as proportional rectangles\n- waterfall: Waterfall chart showing incremental positive and negative changes (for example, an income statement breakdown)"), "component_variant": z.union([z.string(), z.null()]).describe("Component variant (for example, 'simple' or 'financial').").optional(), "config": z.record(z.string(), z.any()).describe("Component configuration data") }).describe("Configuration for a single component in a card.");
export type ComponentConfig = z.infer<typeof ComponentConfig>;

