export const ContentItem = z.object({ "content_format": z.union([z.lazy(() => ContentsFormat), z.null()]).describe("Serialization of the returned card data: 'csv', 'json_records', 'json_compact', or 'card_json'. Null for web text (always returned as raw text) and for a quote-only response (nothing was serialized).").optional(), "cost": z.number().describe("Price of this item in USD. On a quote_only response, it's the most a POST /v1/contents export with the same max_rows can charge. On a search or answer web result, it's the price of fetching the page, because inlined web text is free. On a search, answer, or agent run card without inlined rows, it's export_pricing.baseline_usd, or the most the card's variable-cost minimum can be when that's higher. On any other item, it's what this response billed for it, and those items sum to usage.data.cost_usd. Price an export with export_pricing alone, and don't add this value to that price: they're two prices, not two charges. See https://docs.tako.com/documentation/integrating-tako/contents/pricing.").default(0), "data": z.union([z.string(), z.null()]).describe("Inline payload as text: card data serialized to CSV, or a web page's extracted text. Set only for the 'csv' card format and for web text; null otherwise.").optional(), "records": z.union([z.array(z.record(z.string(), z.union([z.string(), z.number(), z.number().int(), z.boolean(), z.array(z.record(z.string(), z.any())), z.null()]))), z.null()]).describe("Inline card data as verbose JSON: a list of row objects keyed by column name. Set only when content_format is 'json_records'.").optional(), "dataset": z.union([z.lazy(() => TakoDataset), z.null()]).describe("Inline card data as a compact TakoDataset (typed column headers plus positional row arrays). Set only when content_format is 'json_compact'.").optional(), "card_data": z.union([z.record(z.string(), z.any()), z.null()]).describe("Inline card data as a card-type-specific JSON object, set only when content_format is 'card_json'. Its 'card_type' field names the shape, and card_data_schema describes it. Tako cuts its record rows to max_rows, like every other format, and bills the rows it returns. A card type without a card_json shape returns 422 on /contents and falls back to 'json_compact' on search and answer include_contents.").optional(), "card_data_schema": z.union([z.record(z.string(), z.any()), z.null()]).describe("JSON Schema for card_data, so you can learn its shape without reading the payload. Set for every card_json export: inline, by URL, and as a /contents quote. The last two leave card_data null. A search or answer card that you didn't ask to inline has no schema. card_data can omit a field the schema declares when the provider didn't supply it. Null for other formats and for web text.").optional(), "url": z.union([z.string(), z.null()]).describe("Presigned download URL for the content, returned in 'url' delivery mode. Null for inline delivery and for quotes; pair with expires_at.").optional(), "expires_at": z.union([z.string(), z.null()]).describe("ISO-8601 timestamp after which the presigned url stops working. Null whenever url is null.").optional(), "total_rows": z.union([z.number().int(), z.null()]).describe("Rows in the card's data, however many this response returned. Compare it with the rows returned to tell whether a larger max_rows returns more. On a card that lists a capped slice of a larger set, it counts the slice, and total_matching counts the set. On a search or answer list of companies or people, it's the most rows a /contents export returns, and truncated is true. On another search or answer card without inlined rows, it's set only when the card can hold premium values. On an agent run card, it's set only when the card stores its rows, as a people list does. Null for web text.").optional(), "total_matching": z.union([z.number().int(), z.null()]).describe("Size of the whole set behind a card that lists a capped slice of it, such as 330 for a card listing the 30 soonest-closing of 330 open solicitations. A larger max_rows doesn't return more of that set. Null when the card's rows are the whole set, when Tako doesn't count the set (truncated is still true), and for web text.").optional(), "truncated": z.boolean().describe("True when the card holds more rows than Tako returned: max_rows or the card's max_rows_ceiling (at most 100,000) cut the rows, the card lists a capped slice of a larger set (see total_matching), or, on a search or answer response, a /contents export of a list card returns more rows than the card shows. All cards in a search or answer response share a 2,000-billable-row budget and a 20,000-row budget, spent in card order, so a later card can return a short preview or no rows. Its export_pricing still prices a /contents export. See https://docs.tako.com/documentation/integrating-tako/contents/pricing#search-inline-contents-vs-the-contents-api.").default(false), "export_pricing": z.union([z.lazy(() => ExportPricing), z.null()]).describe("Your rate for a POST /v1/contents export of this card, in any format, so you can price the export before you fetch it. Null for web text and other content you can't export.").optional(), "manifest": z.union([z.array(z.lazy(() => ColumnDescriptor)), z.null()]).describe("Per-column metadata, one entry per exported column, in column order: entry i describes column i (CSV header i, json_records key i, or dataset.columns[i]). Each entry carries name (the column header), dtype, unit, metric, entity, and premium_class. On an agent run card, it's set wherever total_rows is. Null for web text and for other quotes that carry no tabular columns.").optional(), "premium": z.boolean().describe("True when this item's premium cells are revealed: a /contents response to premium=true. False on every search and answer card and on a /contents response without the flag. There, a withheld premium cell reads [premium: withheld] in CSV and is null in JSON formats, and redacted_cells says which rows held a value.").default(false), "premium_rows": z.union([z.record(z.string(), z.number().int()), z.null()]).describe("Per premium class ('company_record', 'person_contact'), the number of distinct companies or people that the delivered rows hold a value for in a column of that class, revealed or withheld. Multiply by export_pricing.premium_row_cpm_usd[class] / 1000 to price the premium part of an export. Empty for a card without premium columns, and null for web text. On an agent run card, it counts every row of the card. On a search or answer card that inlines no rows, it counts the rows the card shows, and it's null when the card can't hold a premium value. When truncated is true there, ask /contents with quote_only for the premium price. See https://docs.tako.com/documentation/integrating-tako/contents/pricing#premium-columns.").optional(), "redacted_cells": z.union([z.record(z.string(), z.array(z.number().int())), z.null()]).describe("Column header to the 0-based positions, among the delivered rows, whose premium value was withheld. Present only when a premium cell was withheld; null when premium=true, when nothing was withheld, and for web text. Positions index the delivered rows: CSV data rows in order, json_records entries, or dataset.rows. In CSV, the same cells read [premium: withheld]; a premium cell with no value is blank.").optional(), "source_url": z.string().describe("The originating result URL from the request."), "description": z.union([z.string(), z.null()]).describe("The card's description: what the card shows and what its data says. It describes the whole card, not only the rows this request delivered, so a figure it states may fall outside them. Null for a web URL. For a card that search returned as a placeholder, it describes the data the request unlocked, and it's null when the request fetched no data, such as a `quote_only` request.").optional(), "offset": z.union([z.number().int(), z.null()]).describe("The request's offset, echoed on a Tako card export. Null for web text and quotes.").optional(), "delivery": z.enum(["quote","inline","url"]).describe("How Tako delivered the content. 'quote' means Tako delivered nothing, and cost is a price, not a charge. 'inline' means the content is in data, records, dataset, or card_data. 'url' means you download it from url before expires_at.").readonly().optional() }).describe("A single downloadable artifact.\n\n`delivery` says whether this item is a quote, inline content, or a\ndownload URL. A card_json quote and a card_json `url` delivery also return\n`card_data_schema`, with `card_data` null.");
export type ContentItem = z.infer<typeof ContentItem>;

