export type ContentsDeliveryMode = z.infer<typeof ContentsDeliveryMode>;

export const ContentsFormat = z.enum(["csv","json_records","json_compact","card_json"]).describe("Serialization of tabular (Tako card) data. Web content is always raw text\nand carries no content format (content_format is null).");
