export const ContentsHighlights = z.object({ "query": z.union([z.string(), z.null()]).describe("The question the passages should answer. Omit it to receive the page's leading passages.").optional(), "max_characters": z.number().int().gte(100).lte(20000).describe("Total character budget for the returned passages.").default(4000) }).strict().describe("Return the passages of a web page instead of its full text.");
export type ContentsHighlights = z.infer<typeof ContentsHighlights>;

export const ContentsRequest = z.object({ "url": z.string().describe("The result URL to fetch downloadable content for (a TakoCard.webpage_url or a WebResult.url). A Tako card URL yields a CSV of the card's data; any other URL yields the page's extracted text."), "mode": z.lazy(() => ContentsDeliveryMode).describe("Delivery mode. 'url' returns a presigned download link. 'inline' returns the content in the response body: card data up to 2,000 rows unless max_rows asks for more, up to the card's export_pricing.max_rows_ceiling, at most 100,000 (with total_rows and truncated reported), or web text.").default("url"), "content_format": z.lazy(() => ContentsFormat).describe("Serialization for Tako card data: 'csv', 'json_records', 'json_compact', or 'card_json' (a rich card-type-specific JSON object; not all card types support it). Ignored for web URLs (always text).").default("csv"), "max_rows": z.union([z.number().int().gte(1), z.null()]).describe("Maximum rows a card export returns and bills. Omit it to get the whole card in 'url' mode or 2,000 rows in 'inline' mode. Tako clamps it to the card's export_pricing.max_rows_ceiling (at most 100,000). Every format, card_json included, bills each row it returns at the per-1,000-row rate, plus the per-export baseline. When a card holds more rows than the cap, csv, json_records, and json_compact keep the rows with the latest dates on a card with a date column, even future ones, and the first rows on a card without one. card_json cuts each card type its own way. In every format, a sports card keeps the tabs nearest the one it shows, or an even share of each table. See https://docs.tako.com/documentation/integrating-tako/contents/for-coding-agent#which-rows-a-capped-export-keeps. Web URLs ignore this field. A card export can hold up to 100,000 rows. Don't read a large export directly into a model's context: at about 15 tokens per row, 10,000 rows cost about 150,000 tokens. Write the export to a file, on disk or in memory, and have the agent parse it with code. Give the model only the rows or results it needs.").optional(), "offset": z.number().int().gte(0).lte(100000).describe("Rows to skip before the export starts, in the card's own row order. Use it with max_rows to export one slice of a list, such as rows 100 to 149 with offset=100 and max_rows=50. Only a card whose export keeps its first rows takes an offset: a card with a date column, a sports card, or content_format=card_json returns 422 for any offset above 0. offset plus max_rows can't pass the card's export_pricing.max_rows_ceiling. An offset at or past the last row returns an empty payload, and an API-key caller isn't charged for it. To page through a card, stop when a call returns fewer rows than max_rows, not when truncated turns false. The row order can change between calls. Web URLs ignore this field.").default(0), "max_chars": z.number().int().gte(1).lte(1000000).describe("Character cap on extracted web page text. Ignored for Tako card URLs (they use max_rows). Omit it and Tako returns the full page text, up to the maximum this field allows. To truncate, pass a smaller value.").default(1000000), "quote_only": z.boolean().describe("When true, return the export's price (cost and export_pricing) without fetching content or charging. The item's delivery is 'quote', and a card_json quote also returns card_data_schema but no total_rows. Tako prices the quote from max_rows, defaulted the way an export defaults it, so the quote is an upper bound on the export's charge and calls no data provider. It includes the most a variable-cost source can charge, export_pricing.variable_cost_max_usd. A quote ignores offset, so it can succeed where the export returns 422. An unexportable card still returns 403, and a card type without a card_json shape still returns 422.").default(false), "premium": z.boolean().describe("When true, reveal premium cells and bill them. Premium columns (manifest[].premium_class) are withheld by default: a withheld cell reads [premium: withheld] in CSV and is null in JSON formats. The export charges export_pricing.premium_row_cpm_usd[class] per 1,000 premium records on top of the row rate, and the item's premium_rows reports the counts. To reveal one record, request the URL in its row's tako_url column with premium=true. It has no effect on a card without premium columns or on a web URL. Tako rejects it with content_format=card_json, and refuses it with 403 over the Machine Payments Protocol (MPP) unless quote_only is also true. See https://docs.tako.com/documentation/integrating-tako/contents/pricing#premium-columns.").default(false), "max_cost_usd": z.union([z.number().gte(0).lte(1000000), z.null()]).describe("The most this call can cost, in USD: the export's base price, its row charge, premium records, and per-unit data charges. Before Tako builds the export or reads vendor data, it prices the call the way `quote_only` does. That price is an upper bound, so Tako can refuse a call whose actual charge would have fit. If the price is above this cap, Tako returns a 422 with `error_type` `COST_CAP_EXCEEDED` and the price in `quoted_cost_usd`, and charges nothing. To get under the cap, lower `max_rows` or raise `max_cost_usd`. The cap covers what Tako charges for the response. It doesn't cover a later variable-cost charge for high monthly volume from a source. Omit it for no cap. A `quote_only` request and an MPP request ignore it.").optional(), "highlights": z.union([z.lazy(() => ContentsHighlights), z.null()]).describe("Return only the passages of a web page that match highlights.query, instead of its full text. The passages arrive in the same text payload, joined with ' … ', and max_chars doesn't apply. Tako card URLs reject it, and so do accounts whose web provider can't return highlights. It bills at the same flat rate as full text.").optional(), "zdr": z.union([z.boolean(), z.null()]).describe("Request zero data retention. Set it to true and Tako keeps no copy of the URL in its logs, and fetches a web page only through its zero-data-retention provider. Available only to accounts that Tako has enabled; any other account gets a 403. To turn it on, contact support@tako.com. Omit it for standard retention.").optional() }).strict().describe("Request body for POST /api/v1/contents.\n\nThe caller passes the result URL it wants downloadable content for, and\nthe endpoint detects the right content from the URL itself. A Tako card\nURL resolves to the card's underlying data. Any other URL resolves to\nthe page's extracted full text. `mode` controls delivery: `url` returns a\npresigned download link, and `inline` returns the content in the\nresponse. `content_format` selects the card serialization\n(csv, json_records, json_compact, or card_json); web URLs ignore it\n(always text).");
export type ContentsRequest = z.infer<typeof ContentsRequest>;

export const ContentsResponse = z.object({ "contents": z.array(z.lazy(() => ContentItem)).describe("Downloadable artifacts for the requested URL.").optional(), "request_id": z.string().describe("Unique identifier for this request."), "usage": z.union([z.lazy(() => Usage), z.null()]).optional() }).describe("Response for POST /api/v1/contents.\n\n`contents` is a list so that the contract stays stable if a single result\never yields multiple artifacts. Today it always carries exactly one\nitem.");
export type ContentsResponse = z.infer<typeof ContentsResponse>;

export const CostCapExceededError = z.object({ "error_message": z.string(), "error_type": z.lazy(() => APIErrorType).default("COST_CAP_EXCEEDED"), "quoted_cost_usd": z.number().describe("The most the call would cost, in USD: the price a `quote_only` request returns."), "max_cost_usd": z.number().describe("The `max_cost_usd` cap the request sent, in USD.") }).describe("422 on /contents: the call's quoted price is above its max_cost_usd.");
export type CostCapExceededError = z.infer<typeof CostCapExceededError>;

export const CreateCardRequest = z.object({ "components": z.array(z.lazy(() => ComponentConfig)).describe("Full component configurations"), "title": z.union([z.string(), z.null()]).describe("Card title (falls back to header component title)").optional(), "description": z.union([z.string(), z.null()]).describe("Card description").optional(), "source": z.union([z.string(), z.null()]).describe("Data source attribution (displayed in footer)").optional(), "height": z.union([z.number().int().gte(100).lte(2000), z.null()]).describe("Chart height in pixels. When set, overrides the default aspect-ratio-based height for all chart components in this card. Must be between 100 and 2000.").optional(), "postmessage_embed": z.boolean().describe("When True, the embed iframe operates in postMessage mode. The parent page injects visualization_data via window.postMessage after the iframe loads; the embed URL carries no inline data. The response includes embed_mode='postmessage' when this is True, and embed_mode='post' otherwise.").default(false), "normalize_currencies": z.union([z.string(), z.null()]).describe("Target ISO 4217 currency code (for example, 'USD' or 'EUR'). When set, Tako converts datasets with recognized currency units to this currency with historical exchange rates. Tako also adds a methodology section that explains the conversion.").optional(), "image_ttl_minutes": z.union([z.number().int().gte(1).lte(1440), z.null()]).describe("Minutes to keep the preview image available for download (zero-data-retention (ZDR) cards only). Min 1, max 1440 (24 hours). When set on a ZDR card, Tako generates a temporary preview image and keeps it available for download until the TTL expires. Non-ZDR cards ignore this field.").optional() }).describe("Request model for creating a card directly with components.");
export type CreateCardRequest = z.infer<typeof CreateCardRequest>;

export const DataFreshness = z.object({ "coverage_end": z.union([z.string(), z.null()]).describe("The last data point in the card's data, in ISO 8601 reduced precision at the series' granularity: a year (2026) for an annual series, a month (2026-06) for a monthly or quarterly one, and a date (2026-06-30) for a daily or intraday one. Check the length before you parse it: a date parser reads 2026 as 2026-01-01, the start of the period. It can be in the future when the card includes projections. On a card with tabs, it describes the tab this response built, so cache it against the response, not the card id. Null for card types without a coverage date.").optional(), "data_as_of": z.union([z.string(), z.null()]).describe("Deprecated: use coverage_end. The same point, always as a full ISO date (YYYY-MM-DD). For a series whose points are periods, this date is the period boundary. It is not a day on which Tako observed a value.").optional(), "last_updated": z.union([z.string(), z.null()]).describe("Date Tako last refreshed the underlying data, as an ISO date (YYYY-MM-DD). On a card with tabs this is the ACTIVE tab's refresh date, for the same reason coverage_end is tab-scoped: only the tab this response built is rendered.").optional() }).describe("When the card's data ends and when Tako last refreshed it. Either field\nmay be null when that date is not available for the card type.");
export type DataFreshness = z.infer<typeof DataFreshness>;

export const DataPipelineAnswerEvent = z.object({ "kind": z.literal("data_pipeline_answer").default("data_pipeline_answer"), "id": z.string(), "chart_refs": z.array(z.string()).optional() }).describe("Signals that the data pipeline produced one or more charts for the\nanswer. It carries only chart references. The answer text streams in\n`text` events, and the structured result arrives in the terminal\n`agent_result` event, not here.");
export type DataPipelineAnswerEvent = z.infer<typeof DataPipelineAnswerEvent>;

export const DataSourceSettings = z.object({ "count": z.union([z.number().int().gte(1).lte(20), z.null()]).describe("Maximum number of data cards to return, 1 to 20. Omit it and Tako uses 5, unless a result cap set elsewhere in the request sizes retrieval instead. Fast and instant return at most 4 cards and deep at most 8, whatever count you send.").optional(), "include_contents": z.boolean().describe("Inline this source's underlying data directly in the response. For the Tako data source, that is serialized card data (see content_format). For web results, that is the page text.").default(false), "mode": z.lazy(() => ContentsDeliveryMode).describe("Delivery for inlined card data when include_contents is true. For Tako cards, include_contents always returns the most-recent rows in the response body, up to max_rows, or up to the default inline row cap for your account if you omit max_rows. This field therefore has no effect on Tako cards; it stays for schema stability. total_rows and truncated on the returned content indicate when more data is available. For a presigned download link, call POST /api/v1/contents with mode='url'.").default("inline"), "content_format": z.lazy(() => ContentsFormat).describe("Serialization for card data: 'json_compact', 'json_records', 'csv', or 'card_json'. The first three return a row-capped preview. 'card_json' returns a rich card-type-specific JSON object under card_data, truncated to the same row cap. Tako bills the rows it returns on every one of the four. A card type with no card_json shape falls back to 'json_compact' for that card.").default("json_compact"), "max_rows": z.union([z.number().int().gte(1), z.null()]).describe("Maximum rows to inline per card when include_contents is true. Omit it to use your account's inline row cap, which is smaller than a /contents export's default because each card bills separately. Tako clamps it to the card's export_pricing.max_rows_ceiling (at most 100,000). Inlined rows bill at the POST /api/v1/contents rate: a per-card baseline plus the per-1,000-row rate. All cards in a response share a 2,000-billable-row budget and a 20,000-row budget, so a later card can return fewer rows or none. Check truncated, and fetch the rest with POST /api/v1/contents. See https://docs.tako.com/documentation/integrating-tako/contents/pricing#search-inline-contents-vs-the-contents-api. A card export can hold up to 100,000 rows. Don't read a large export directly into a model's context: at about 15 tokens per row, 10,000 rows cost about 150,000 tokens. Write the export to a file, on disk or in memory, and have the agent parse it with code. Give the model only the rows or results it needs.").optional(), "node_ids": z.array(z.string()).max(20).describe("Graph node ids to pin into the search, from /v1/graph/search or /v1/graph/related. For example, pin a company, one of its segments, and a metric to get that segment's figures without wording the query exactly. Pinned nodes always become retrieval candidates and get a strong boost; organic results do not change. Ids are not durable across knowledge-graph rebuilds: the search skips an id that no longer resolves (in strict mode it simply cannot match). Malformed ids fail the request with a 400. Max 20.").optional(), "strict": z.boolean().describe("When true, return only data cards that match at least one node in node_ids (which must then be non-empty). When false, pinned nodes rank first but organic results still return. Web results do not change either way.").default(false), "variable_cost": z.union([z.boolean(), z.null()]).describe("Return data from sources priced per unit, such as web traffic and SEO data. Defaults to true. Each such card served with its data has a minimum charge, whether or not its rows are inlined, and the card's `content.export_pricing.variable_cost_max_usd` bounds it. The request's `usage.compute` price counts toward those minimums, but inline data charges don't. The response's `usage` object reports any amount above it as `variable_cost`. Set it to false and each such card is a placeholder with its title, a description and no data points. An account that isn't served variable-cost data always gets placeholders, whatever it sends. To get a placeholder's data, request the card's URL from POST /api/v1/contents.").optional(), "max_variable_cost_usd": z.union([z.number().gte(0).lte(1000000), z.null()]).describe("The most this response pays as `usage.variable_cost`, in USD. Before Tako fetches a card priced per unit, it checks the card's `variable_cost_max_usd` against what's left of this cap, in rank order. A card that doesn't fit is a placeholder whose `placeholder.reason` is `over_cap`, and Tako fetches none of its data. Because the check uses each card's maximum, a card can be withheld when its actual charge would have fit. Send 0 to pay no variable cost with this response: Tako then serves data only for the cards whose minimum the request's `usage.compute` price covers. The cap doesn't cover a later variable-cost charge for high monthly volume from a source. Omit it for no cap. You can't send it with `variable_cost` set to false.").optional() }).strict().describe("Tako data (card) source settings. It adds the two contents-export\nfields on top of the base count and include_contents. Web sources use the\nbase SourceSettings: Tako always inlines web content as raw text, so web\ncarries neither field.");
export type DataSourceSettings = z.infer<typeof DataSourceSettings>;

export const EnrichInputError = z.object({ "error_message": z.string(), "error_type": z.lazy(() => APIErrorType).default("BAD_REQUEST"), "code": z.string(), "field": z.string(), "suggestions": z.array(z.string()).default([]) }).describe("Input the API can't run. code is a list-screen error code (such as unknown_industry), or one of\ninvalid_body (the body isn't valid JSON), invalid_value, no_filters,\ncontacts_need_a_filter, unavailable_filter and unknown_person. field is the request field at fault, or \"\" for an\nerror about the whole request. suggestions holds near-miss values to use instead.");
export type EnrichInputError = z.infer<typeof EnrichInputError>;

