export const ExportPricing = z.object({ "baseline_usd": z.number().describe("Flat USD charged once per card export, independent of row count."), "row_cpm_usd": z.number().describe("USD charged per 1,000 rows delivered. Card-level rate; use this value rather than deriving one from the card's sources. It is the sum of the rates of the card's separately priced data feeds, or the standard rate once for a card with none. Credited producers and cited web pages never add to it. This is 0 if your account's row charges are waived, in which case an export costs baseline_usd whatever its size."), "premium_row_cpm_usd": z.record(z.string(), z.number()).describe("USD charged per 1,000 premium records, keyed by premium class ('company_record', 'person_contact'), added on top of row_cpm_usd when a /contents export passes premium=true. A premium record is a distinct company or person that the delivered rows hold a non-null value for in a column of that class; the item's premium_rows reports the count per class. Empty when the card has no premium columns. Not affected by a row-charge waiver.").optional(), "free_rows": z.number().int().describe("Deprecated and always 0. Row allowances are gone: an account that pays nothing per row now reports row_cpm_usd of 0 instead, which the cost formula already accounts for. Stop reading this field; it will be removed.").default(0), "max_rows_ceiling": z.number().int().describe("Hard cap on rows a single export can return and bill; a larger requested max_rows is clamped to this. No format bills more than the clamped max_rows, and none bills more rows than it returns. Every format obeys this ceiling, including card_json."), "variable_cost_max_usd": z.union([z.number(), z.null()]).describe("Set only for a card with data from a source priced per unit: the most the source's minimum charge for an export of this card can be. An export charges whichever is larger, its own price or that minimum, and the quoted cost already accounts for it. The minimum is known only after the export, so the actual charge can be lower. The export's usage.variable_cost reports a different amount: only what the export charged above its own price. On a search or answer card, it also bounds the minimum charge for serving that card with its data.").optional() }).describe("Your rate for a POST /v1/contents export of this card, so you can price\nthe export before you fetch it.\n\nAn export costs baseline_usd + row_cpm_usd * rows / 1000, where rows is the\nnumber of rows it returns, at most max_rows_ceiling. An export that passes\npremium=true adds premium_row_cpm_usd[class] * premium_rows[class] / 1000\nfor each premium class. For a card with variable-cost data, the export\ncharges the larger of that price and the source's minimum, which is at most\nvariable_cost_max_usd.");
export type ExportPricing = z.infer<typeof ExportPricing>;

export const FlatResult = z.object({ "type": z.lazy(() => TakoSourceIndex).describe("data for a Tako card, web for a web page."), "title": z.union([z.string(), z.null()]).optional(), "url": z.union([z.string(), z.null()]).describe("The card page for a card, the page URL for a web result.").optional(), "snippet": z.union([z.string(), z.null()]).describe("Markdown. For a card: the data description, then sections headed ### Sources, ### Methodology, and ### Metrics, each omitted when empty. For a web page: the matching excerpt.").optional(), "published_date": z.union([z.string(), z.null()]).describe("Calendar date, YYYY-MM-DD, or null. For a card, the date Tako last refreshed the data. For a web page, its publication date.").optional(), "sources": z.array(z.lazy(() => ResultSource)).describe("Publishers behind this result.").optional(), "relevance": z.union([z.lazy(() => KnowledgeCardRelevance), z.null()]).describe("Tako's relevance label for a card. Omitted for a web page. On `effort: deep` an LLM scores cards as integers 1 to 5, so a 5 is High and a 4 is Medium. A card the LLM leaves unscored keeps its continuous retrieval score and can be High below 5. Other efforts score continuously and can label the same card higher.").optional(), "content": z.union([z.lazy(() => ResultContent), z.null()]).optional(), "image_url": z.union([z.string(), z.null()]).describe("Chart image for a card. Omitted for a web page.").optional(), "card_id": z.union([z.string(), z.null()]).describe("Tako card id. Omitted for a web page.").optional() }).describe("One row of results: a Tako card or a web page in the same shape.");
export type FlatResult = z.infer<typeof FlatResult>;

export const FlatResultsSettings = z.object({ "max_results": z.union([z.number().int().gte(1).lte(40), z.null()]).describe("The number of results you want in results. The range is 1 to 40. Each source retrieves up to this many, capped at 20, unless you gave that source its own count, which always stands. Either way Tako cuts the merged list to this length, dropping Low-relevance cards first, then trailing web results, then trailing Medium-relevance cards, then trailing High-relevance cards. High- and Medium-relevance cards rank above every web result, so a small max_results can return cards alone. Omit it for no cut.").optional(), "snippet_max_chars": z.union([z.number().int().gte(1).lte(20000), z.null()]).describe("Character cap on every snippet in results. Tako sends it to the web source as its snippet cap and truncates card snippets by section. Don't combine it with sources.web.snippet_max_chars; Tako rejects a request that sets both. Omit it for no cap.").optional() }).strict().describe("Settings for the flat results mode. Sending this object turns the mode\non. Send an empty object to turn it on with defaults.");
export type FlatResultsSettings = z.infer<typeof FlatResultsSettings>;

export const GeoLocation = z.object({ "latitude": z.number().gte(-90).lte(90).describe("Latitude of the end user (degrees, -90 to 90)."), "longitude": z.number().gte(-180).lte(180).describe("Longitude of the end user (degrees, -180 to 180).") }).strict();
