export const GraphNode = z.object({ "id": z.string().describe("Opaque, human-friendly public id (<prefix>::<name>::<hash>, where prefix is ent for an entity or mt for a metric). Ids are not durable across knowledge-graph rebuilds — resolve them at request time rather than storing them."), "type": z.lazy(() => GraphNodeType).describe("Whether the node is a metric or an entity."), "name": z.string().describe("Display name. Several metrics can share a name when publishers report different series, such as two GDP metrics; read `description` to tell them apart."), "aliases": z.array(z.string()).describe("Other names Tako matches to this node, such as abbreviations, tickers, and former names. /v1/graph/search matches `q` against these as well as `name`.").optional(), "description": z.union([z.string(), z.null()]).describe("What the node is. For a metric, what it measures, often with its unit and basis. For an entity, a short identification. Absent when Tako has none.").optional(), "subtype": z.union([z.lazy(() => EntityClassName), z.null()]).describe("The entity's class, such as Companies, Countries, or People. Absent for metrics, and for an entity whose class Tako didn't resolve for this response. /v1/graph/search and /v1/graph/related resolve it; /v1/graph/node doesn't.").optional(), "label": z.union([z.lazy(() => NerLabel), z.null()]).describe("Public NER label of the node (PERSON, ORG, GPE, ...). Derived from the node's stored annotation; null when the internal annotation has no public equivalent.").optional(), "match_kind": z.union([z.lazy(() => GraphMatchKind), z.null()]).describe("How this result matched `q`: `name` when `q` is the node's name, `alias` when `q` is one of its aliases, `mention` when a phrase in `q` is the node's name or alias (Apple Inc. for `q=Apple revenue`), and `fuzzy` for any other partial or approximate match. A `fuzzy` result can be unrelated to what you asked for, so check it before you rely on it. Set on /v1/graph/search results only.").optional() });
export type GraphNode = z.infer<typeof GraphNode>;

