export const RetrievalAgentRunRequest = z.object({ "query": z.string().describe("Natural-language data-retrieval request for the retrieval agent."), "thread_id": z.union([z.string().uuid(), z.null()]).describe("Existing thread to continue (follow-up). Omit to start a new thread.").optional(), "effort": z.union([z.lazy(() => RetrievalAgentEffort), z.null()]).describe("Retrieval-agent effort. Only 'medium' is supported; omit it and Tako uses medium.").optional(), "source_indexes": z.union([z.array(z.enum(["data","web"])), z.null()]).describe("Which sources the agent may use: 'data' (curated knowledge), 'web' (open-web search), or both. Omit it on a new thread and the agent uses both; omit it on a follow-up and the run keeps the thread's sources. Tako accepts the legacy value 'tako' as a synonym for 'data'.").optional(), "cards": z.boolean().describe("Whether the agent may build visualization cards. True is permissive: the agent may build cards, but it does not have to (a completed run with no cards is legitimate). Set false to suppress card building entirely.").default(true), "output_schema": z.union([z.record(z.string(), z.any()), z.null()]).describe("JSON Schema for structured output. The agent writes the synthesized fields. Dataset slots (marked with x-tako-dataset: true) receive exact retrieved rows as a TakoDataset. Supported subset: the object, array, string, number, integer, and boolean types, plus enum, required, and description. Caps: 16KB, depth 5, 64 properties, 4 dataset slots. Violations return 400 output_schema_invalid.").optional(), "locale": z.string().describe("BCP-47 locale. Drives the language of the agent's answer and the locale used when rendering card preview images.").default("en-US"), "timezone": z.union([z.string(), z.null()]).describe("IANA timezone (for example, 'America/New_York'). The agent uses it to render dates and times in card preview images. It does not affect the returned data.").optional(), "output_settings": z.union([z.lazy(() => AgentOutputSettings), z.null()]).describe("Settings that control the response and rendering.").optional() }).describe("Request body for POST /v1/agent/retrieval/runs.");
export type RetrievalAgentRunRequest = z.infer<typeof RetrievalAgentRunRequest>;

export const RetrievalAgentRunSummary = z.object({ "run_id": z.string(), "status": z.lazy(() => AgentRunStatus), "created_at": z.string(), "completed_at": z.union([z.string(), z.null()]).optional(), "thread_id": z.union([z.string(), z.null()]).optional(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional(), "object": z.literal("agent.retrieval.run").default("agent.retrieval.run") });
export type RetrievalAgentRunSummary = z.infer<typeof RetrievalAgentRunSummary>;

export const RetrievalAgentStreamEnvelope = z.object({ "seq": z.number().int().gte(0), "run_id": z.string(), "thread_id": z.union([z.string(), z.null()]).optional(), "category": z.lazy(() => StreamCategory), "block": z.any().superRefine((x, ctx) => {
    const schemas = [z.lazy(() => ToolCallEvent), z.lazy(() => ToolResultEvent), z.lazy(() => ToolErrorEvent), z.lazy(() => ToolRetryEvent), z.lazy(() => StatusEvent), z.lazy(() => SubagentEvent), z.lazy(() => ReasoningEvent), z.lazy(() => TextEvent), z.lazy(() => DataPipelineAnswerEvent), z.lazy(() => RetrievalAgentResultEvent), z.lazy(() => RunSummaryEvent), z.lazy(() => HeartbeatEvent), z.lazy(() => StreamResetEvent), z.lazy(() => StreamDoneEvent)];
    const { errors, failed } = schemas.reduce<{
      errors: z.core.$ZodIssue[];
      failed: number;
    }>(
      ({ errors, failed }, schema) =>
        ((result) =>
          result.error
            ? {
                errors: [...errors, ...result.error.issues],
                failed: failed + 1,
              }
            : { errors, failed })(
          schema.safeParse(x),
        ),
      { errors: [], failed: 0 },
    );
    const passed = schemas.length - failed;
    if (passed !== 1) {
      ctx.addIssue(errors.length ? {
        path: [],
        code: "invalid_union",
        errors: [errors],
        message: "Invalid input: Should pass single schema. Passed " + passed,
      } : {
        path: [],
        code: "custom",
        errors: [errors],
        message: "Invalid input: Should pass single schema. Passed " + passed,
      });
    }
  }) }).describe("Public SSE envelope for the Retrieval Agent run stream. It has the same\nwire shape as AgentStreamEnvelope. The only difference is that the\nterminal agent_result block carries RetrievalAgentResult (unified\ntop-level citations, no web_results), so the SSE terminal matches the\nGET poll result.");
export type RetrievalAgentStreamEnvelope = z.infer<typeof RetrievalAgentStreamEnvelope>;

export const RunSummaryEvent = z.object({ "kind": z.literal("run_summary").default("run_summary"), "status": z.lazy(() => AgentRunStatus), "created_at": z.string(), "completed_at": z.union([z.string(), z.null()]).optional(), "error": z.union([z.lazy(() => ErrorObject), z.null()]).optional(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional() }).describe("Terminal run metadata. The stream sends it once, right before\nstream_done, with the GET-poll run fields the stream otherwise lacks.\nstatus, created_at, and completed_at are always present. error appears\nonly on a failed run. usage appears only on a metered (pay-as-you-go) run\nand is null otherwise.\n\nagent_result plus run_summary equals the GET poll object, except that for\nup to 30 seconds after a run completes, the poll can still report it\nrunning. Treat this frame's status as authoritative.\n\nIt shares the envelope `seq` of the stream_done that follows it and\nadvances no resume cursor. Identify it by `kind`.");
export type RunSummaryEvent = z.infer<typeof RunSummaryEvent>;

export const SearchEffortLevel = z.enum(["fast","instant","deep"]).describe("Effort for search and answer. `fast` is the default. `instant` serves\ncached cards without a new data retrieval. On /v1/answer, `instant` also\nwrites the answer with the fastest model, trading answer quality for\nspeed, while `fast` and `deep` use a stronger model. `deep` also searches\nmore of Tako's data and reranks the results a second time. It's slower,\nand it bills at a premium rate.");
export type SearchEffortLevel = z.infer<typeof SearchEffortLevel>;

export const SearchRequest = z.object({ "query": z.string().regex(new RegExp("\\S")).min(1).describe("Natural language search query."), "effort": z.lazy(() => SearchEffortLevel).describe("Search effort level: 'fast', 'instant', or 'deep'.").default("fast"), "sources": z.lazy(() => Sources).describe("Per-source settings. The search includes an index only if its key is present. Omit it and Tako searches data and web with no counts set. Tako accepts the legacy key 'tako' as a synonym for 'data'.").optional(), "location": z.union([z.lazy(() => GeoLocation), z.null()]).describe("Optional coordinates of the end user. Resolves the location for implicit-location queries (for example, weather) and, when `timezone` is absent, the timezone Tako renders preview images in. An explicit location in the query overrides these coordinates.").optional(), "country_code": z.string().describe("ISO 3166-1 alpha-2 country code for localization.").default("US"), "locale": z.string().describe("BCP-47 locale tag for language and formatting.").default("en-US"), "timezone": z.union([z.string(), z.null()]).describe("IANA timezone (for example, 'America/New_York') Tako renders preview images in. Defaults to the zone at `location` when you send coordinates. Card text keeps each surface's own timezone.").optional(), "output_settings": z.union([z.lazy(() => OutputSettings), z.null()]).describe("Settings that control the response shape.").optional(), "include_related": z.union([z.number().int().gte(1).lte(20), z.null()]).describe("Applies to POST /v3/search only. Return follow-up query suggestions in `related`. Omit this field to disable them. The value sets the maximum number of suggestions, from 1 to 20. POST /v1/answer accepts this field but ignores it: the answer response has no `related` field.").optional(), "variable_cost": z.union([z.boolean(), z.null()]).describe("Deprecated: send `sources.data.variable_cost` instead. Tako reads this field only when `sources.data.variable_cost` is absent, and answers 400 when the two disagree.").optional(), "zdr": z.union([z.boolean(), z.null()]).describe("Request zero data retention. Set it to true and Tako keeps no copy of the query in its logs or saved cards, and limits web retrieval to its zero-data-retention provider. Available only to accounts that Tako has enabled; any other account gets a 403. To turn it on, contact support@tako.com. Omit it for standard retention.").optional() }).strict().describe("Shared request for POST /api/v3/search and POST /api/v1/answer.");
export type SearchRequest = z.infer<typeof SearchRequest>;

export const SearchResponse = z.object({ "cards": z.array(z.lazy(() => TakoCard)).optional(), "web_results": z.array(z.lazy(() => WebResult)).optional(), "request_id": z.string(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional(), "related": z.union([z.array(z.lazy(() => RelatedSuggestion)), z.null()]).describe("Follow-up queries you can run next. Set `include_related` on the request to receive them. Absent when you did not ask for them, or when Tako found none.").optional(), "results": z.union([z.array(z.lazy(() => FlatResult)), z.null()]).describe("Cards and web results as one list, present only when the request set output_settings.flat_results. cards and web_results are then empty.").optional() });
