export const TakoCard = z.object({ "card_id": z.union([z.string(), z.null()]).optional(), "title": z.union([z.string(), z.null()]).optional(), "description": z.union([z.string(), z.null()]).optional(), "semantic_description": z.union([z.string(), z.null()]).optional(), "webpage_url": z.union([z.string(), z.null()]).optional(), "image_url": z.union([z.string(), z.null()]).optional(), "embed_url": z.union([z.string(), z.null()]).optional(), "sources": z.union([z.array(z.lazy(() => TakoCardSource)), z.null()]).optional(), "methodologies": z.union([z.array(z.lazy(() => KnowledgeCardMethodology)), z.null()]).optional(), "source_indexes": z.union([z.array(z.lazy(() => TakoSourceIndex)), z.null()]).optional(), "card_type": z.union([z.string(), z.null()]).optional(), "relevance": z.union([z.lazy(() => KnowledgeCardRelevance), z.null()]).describe("Tako's relevance label for this card, from the same ladder the flat `results` relevance uses. On `effort: deep` an LLM scores cards as integers 1 to 5, so a 5 is High and a 4 is Medium. A card the LLM leaves unscored keeps its continuous retrieval score and can be High below 5. Other efforts score continuously and can label the same card higher.").optional(), "content": z.union([z.lazy(() => ResultContent), z.null()]).optional(), "exportable": z.boolean().describe("Whether the /contents endpoint can download this card's data. false means the export is not available; use the card's chart and inline preview instead. true means the export is eligible but not guaranteed; the /contents endpoint can still return 403, so fall back to the preview on error.").default(false), "relevance_score": z.union([z.number(), z.null()]).describe("Numeric relevance of this card to the query on a 1.0-5.0 scale (5.0 = exact match; higher is more relevant). Only populated for entitled accounts; null otherwise.").optional(), "nodes": z.union([z.array(z.lazy(() => TakoCardNode)), z.null()]).describe("Graph nodes (entities and metrics) behind this card. The response includes them by default. Absent for web-only cards or when node resolution was not available. Use each id with /v1/graph/node/{id} for full detail (aliases, subtype), or pass ids in sources.data.node_ids to pin these nodes in future searches.").optional(), "metric_definitions": z.union([z.array(z.lazy(() => MetricDefinition)), z.null()]).describe("Definitions of the metrics this card displays (name + definition). Null when no displayed metric has a definition available.").optional(), "data_freshness": z.union([z.lazy(() => DataFreshness), z.null()]).describe("Freshness dates for the card's data: where the data ends (coverage_end), the same point as a full date (data_as_of, deprecated), and the last refresh date (last_updated). Null when no date is available.").optional(), "placeholder": z.union([z.lazy(() => PlaceholderInfo), z.null()]).describe("Set when the card is a placeholder: it carries its title and no data points, because its source charges for each request and this response didn't include that source's data. A search returns a placeholder when the request sets variable_cost to false, for every request paid through the Machine Payments Protocol (MPP), and for an account that isn't served variable-cost data. Null on every card that carries its data.").optional() }).describe("A Tako knowledge card on the search and answer surfaces. It carries a\n`content` download descriptor.");
export type TakoCard = z.infer<typeof TakoCard>;

export const TakoCardNode = z.object({ "id": z.string().describe("Opaque, human-friendly public id (<prefix>::<name>::<hash>, where prefix is ent for an entity or mt for a metric). Ids are not durable across knowledge-graph rebuilds — resolve them at request time rather than storing them."), "type": z.lazy(() => GraphNodeType).describe("Whether the node is a metric or an entity."), "name": z.string().describe("Display name. Several metrics can share a name when publishers report different series, such as two GDP metrics; read `description` to tell them apart."), "description": z.union([z.string(), z.null()]).describe("What the node is. For a metric, what it measures, often with its unit and basis. For an entity, a short identification. Absent when Tako has none.").optional() }).describe("Slim graph node for the search and answer card surface\n(TakoCard.nodes). It is deliberately narrower than GraphNode: it carries\nno `aliases` and no `subtype`. For a node's aliases, resolve the id via\n/v1/graph/node/{id}; for an entity's subtype, use /v1/graph/related.");
