export const TakoCardSource = z.object({ "source_name": z.union([z.string(), z.null()]).describe("The name of the source").optional(), "source_description": z.union([z.string(), z.null()]).describe("The description of the source").optional(), "source_index": z.lazy(() => TakoSourceIndex).describe("The index of the source"), "url": z.union([z.string(), z.null()]).describe("The URL of the source").optional(), "source_text": z.union([z.string(), z.null()]).describe("Raw excerpts retrieved from the source page — the unmodified web content that grounded the answer. Set for `web` sources; null for `data` sources.").optional() }).describe("A source that backs a TakoCard on the SDK surfaces. It uses the\n{data, web} TakoSourceIndex taxonomy.");
