export const TakoDatasetColumn = z.object({ "name": z.string().describe("Column name."), "type": z.lazy(() => TakoDatasetColumnType).describe("Logical column type: 'string', 'number', 'boolean', 'date', 'datetime', or 'array'. Temporal cells are ISO-8601 strings. An 'array' column holds an array of objects, or null."), "unit": z.union([z.string(), z.null()]).describe("Structured unit for the column values, e.g. 'USD billions', '%'. Null when unitless.").optional() }).describe("Typed header entry; `type` is the JSON-facing column type.");
