export const Usage = z.object({ "total_cost_usd": z.number().describe("Total quoted USD cost of this request: the sum of the components present."), "compute": z.union([z.lazy(() => UsageCompute), z.null()]).describe("Compute cost breakdown. Present only on surfaces with a compute step (absent for contents).").optional(), "data": z.union([z.lazy(() => UsageData), z.null()]).describe("Inline-data cost breakdown. Present only when the surface emitted billable inline data.").optional(), "variable_cost": z.union([z.lazy(() => UsageVariableCost), z.null()]).describe("Variable-cost charge. Present only when data from a source priced per unit had a minimum charge above the request's base price: on a search or answer request that served such a card with its data, where the base price is `usage.compute` and inline data charges don't count toward the minimum; on a contents export of such a card, where it's the export's price; and on an agent run once it completes, where it's the run's price.").optional() }).describe("Usage for one metered request. `total_cost_usd` is always present (the\ntotal quoted charge). `compute`, `data`, and `variable_cost` are the\nadditive breakdown; each appears only where it applies. total_cost_usd always equals the sum\nof the components that appear.");
