export const WebResult = z.object({ "title": z.string().describe("Title of the web page."), "url": z.string().describe("URL of the web page."), "snippet": z.union([z.string(), z.null()]).describe("Excerpt(s) from the page that matched the query.").optional(), "source_name": z.union([z.string(), z.null()]).describe("Publisher or domain name, when Tako can extract it from the URL.").optional(), "publish_date": z.union([z.string(), z.null()]).describe("Publication date of the page, when available.").optional(), "content": z.union([z.lazy(() => ResultContent), z.null()]).describe("Downloadable content descriptor for this result, fetched via the Contents endpoint. Web results are always downloadable as text. None for callers that do not populate it.").optional() }).describe("A single raw web search result from the `web` source index.\n\nDistinct from `KnowledgeCardSource` (a citation inside a synthesized\nanswer) and `KnowledgeCard` (a Tako visualization). Web results are\nraw retrieval output — title, URL, optional snippet. They do not depend\non any LLM synthesis that may also happen over them.");
