export const WebSourceSettings = z.object({ "count": z.union([z.number().int().gte(1).lte(20), z.null()]).describe("Maximum number of web results to return, 1 to 20. Omit it and Tako uses 5 on search and 3 on answer, unless a result cap set elsewhere in the request sizes retrieval instead.").optional(), "include_contents": z.boolean().describe("Inline the page text of each web result in the response. Tako returns it free of charge, on a best-effort basis: if a page's text isn't available at search time, content.data is null. To fetch a page directly, use POST /api/v1/contents.").default(false), "category": z.union([z.lazy(() => WebCategory), z.null()]).describe("Restrict web results to a category. 'news' filters to news sources. 'sports' and 'finance' are accepted but have no effect yet. Omit for a general web search.").optional(), "include_domains": z.array(z.string()).max(20).describe("Return only results from these domains. Max 20. Send a bare host that includes a top-level domain: 'cnn.com', not 'cnn'.").optional(), "exclude_domains": z.array(z.string()).max(20).describe("Drop results from these domains. Max 20. Send a bare host that includes a top-level domain: 'cnn.com', not 'cnn'.").optional(), "snippet_max_chars": z.union([z.number().int().gte(1).lte(20000), z.null()]).describe("Character cap on the text excerpt returned per web result, up to 20000. Omit it and Tako uses 4000 on search and 1000 on answer, unless Tako has agreed a different cap for your account. Send a value and Tako uses it exactly.").optional(), "highlights": z.boolean().describe("Return query-relevant highlight passages as each web result's snippet, instead of the page's opening text. Highlights stay within snippet_max_chars. Unless you also set include_contents, Tako fetches no page text, so a page with no highlight returns snippet: null. A snippet can join passages from different parts of the page with ' … ', so it isn't one continuous quote.").default(false), "article_content_max_chars": z.number().int().gte(1).lte(1000000).describe("Character cap on the full article text when include_contents is true.").default(30000), "published_after": z.union([z.string().date(), z.null()]).describe("Keep only web results published on or after this date (ISO 'YYYY-MM-DD'). Tako applies the date on the provider where possible, and always filters the returned results. Results with no known publication date are kept. Omit for no lower bound.").optional(), "published_before": z.union([z.string().date(), z.null()]).describe("Keep only web results published on or before this date (ISO 'YYYY-MM-DD'). Results with no known publication date are kept. Omit for no upper bound.").optional() }).strict().describe("Web source settings. Adds category, domain filters, and character caps\non top of the base count and include_contents.");
export type WebSourceSettings = z.infer<typeof WebSourceSettings>;
